package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditPersonHeld {
    public void audit(@Val Person loaded, @Val PersonResponse held, ServerHttpConnection connection, Audit audit) {
        PersonResponse.Held hold = held.holds().get(held.holds().size() - 1);
        audit.record(Audit.line("PERSON_HELD", loaded.sheetId(), Audit.user(connection), "name=" + held.name(),
                "from=" + held.added().from()));
    }
}
EOF

